def transform(grid):
    a = [row[:] for row in grid]
    h, w = len(a), len(a[0])
    bg = Counter(v for row in a for v in row).most_common(1)[0][0]
    edges = Counter()
    for c in range(w):
        if a[0][c] != bg: edges[a[0][c]] += 1
        if a[h-1][c] != bg: edges[a[h-1][c]] += 1
    for r in range(1, h-1):
        if a[r][0] != bg: edges[a[r][0]] += 1
        if a[r][w-1] != bg: edges[a[r][w-1]] += 1
    if not edges:
        return a
    rail = edges.most_common(1)[0][0]
    horizontal = sum(v == rail for v in a[0]) + sum(v == rail for v in a[h-1])
    vertical = sum(a[r][0] == rail for r in range(h)) + sum(a[r][w-1] == rail for r in range(h))
    markers = [(r, c, a[r][c]) for r in range(h) for c in range(w)
               if a[r][c] not in (bg, rail) and 0 < r < h-1 and 0 < c < w-1]
    if not markers:
        return a
    if horizontal >= vertical:
        top = _runs(a[0], rail)
        bottom = _runs(a[h-1], rail)
