                for r in range(1, h-1):
                    if a[r][c] == bg:
                        a[r][c] = markers[0][2]
        # Interior points extend toward the lower boundary; their tip is marked 4.
        for r, c, color in markers:
            a[r][c] = 4
            for rr in range(r+1, h-1):
                if a[rr][c] == bg:
                    a[rr][c] = color
    else:
        left = _runs([a[r][0] for r in range(h)], rail)
        right = _runs([a[r][w-1] for r in range(h)], rail)
        for r, c, color in markers:
            side = None
            seg = None
            for candidate, segs in ((0, left), (w-1, right)):
                for lo, hi in segs:
                    if lo <= r <= hi:
                        if side is None or abs(c-candidate) < abs(c-side):
                            side, seg = candidate, (lo, hi)
            if side is None:
                side = 0 if c < w/2 else w-1
            # Draw from the point to its own border, leaving the border intact.
            step = 1 if side == 0 else -1
            cc = c - step
            while 0 < cc < w-1:
                if a[r][cc] == bg:
                    a[r][cc] = color
                cc -= step
            a[r][c] = 4
            # Mirror the row into the paired boundary band on the opposite side.
            other = right if side == 0 else left
            if seg is not None and other:
                lo, hi = seg
                match = min(other, key=lambda q: abs((q[1]-q[0]) - (hi-lo)) + abs(q[0]-lo))
                rr = match[0] + (r-lo)
                if match[0] <= rr <= match[1]:
                    for x in range(1, w-1):
                        if a[rr][x] == bg:
                            a[rr][x] = color
    return a
