source2='''from collections import Counter


def _runs(values, target):
    out = []
    start = None
    for i, value in enumerate(values + [None]):
        if value == target and start is None:
            start = i
        elif value != target and start is not None:
            out.append((start, i - 1))
            start = None
    return out


def _paired(seg, candidates):
    lo, hi = seg
    return min(candidates, key=lambda q: (abs((q[1] - q[0]) - (hi - lo)), abs(q[0] - lo)))


def transform(grid):
    a = [row[:] for row in grid]
    h, w = len(a), len(a[0])
    bg = Counter(v for row in a for v in row).most_common(1)[0][0]
    edge_counts = Counter()
    for c in range(w):
        if a[0][c] != bg: edge_counts[a[0][c]] += 1
        if a[h-1][c] != bg: edge_counts[a[h-1][c]] += 1
    for r in range(1, h-1):
        if a[r][0] != bg: edge_counts[a[r][0]] += 1
        if a[r][w-1] != bg: edge_counts[a[r][w-1]] += 1
    if not edge_counts:
        return a
    rail = edge_counts.most_common(1)[0][0]
    hc = sum(x == rail for x in a[0]) + sum(x == rail for x in a[h-1])
    vc = sum(a[r][0] == rail for r in range(h)) + sum(a[r][w-1] == rail for r in range(h))
    markers = [(r, c, a[r][c]) for r in range(1, h-1) for c in range(1, w-1)
               if a[r][c] not in (bg, rail)]
    if not markers:
        return a
    if hc >= vc:
        top = _runs(a[0], rail)
        bottom = _runs(a[h-1], rail)
        for r, c, color in markers:
            candidates = []
            for side, segs in (('top', top), ('bottom', bottom)):
                for seg in segs:
                    if seg[0] <= c <= seg[1]:
                        candidates.append((abs(r - (0 if side == 'top' else h-1)), side, seg))
            if not candidates:
                side = 'top' if r <= h/2 else 'bottom'
                src = None
            else:
                _, side, src = min(candidates)
            opposite = bottom if side == 'top' else top
            if src is not None and opposite:
                dstseg = _paired(src, opposite)
                dc = dstseg[0] + c - src[0]
                if dstseg[0] <= dc <= dstseg[1]:
                    for rr in range(1, h-1):
                        if a[rr][dc] == bg:
                            a[rr][dc] = color
            # Extend the point toward the matching edge and mark its tip.
            a[r][c] = 4
            dr = -1 if side == 'top' else 1
            rr = r + dr
            while 0 < rr < h-1:
                if a[rr][c] == bg:
                    a[rr][c] = color
                rr += dr
    else:
        left = _runs([a[r][0] for r in range(h)], rail)
        right = _runs([a[r][w-1] for r in range(h)], rail)
        for r, c, color in markers:
            candidates = []
            for side, segs in ((0, left), (w-1, right)):
                for seg in segs:
                    if seg[0] <= r <= seg[1]:
                        candidates.append((abs(c-side), side, seg))
            if candidates:
                _, side, src = min(candidates)
            else:
                side = 0 if c < w/2 else w-1
                src = None
            step = 1 if side == 0 else -1
            cc = c - step
            while 0 < cc < w-1:
                if a[r][cc] == bg:
                    a[r][cc] = color
                cc -= step
            a[r][c] = 4
            opposite = right if side == 0 else left
            if src is not None and opposite:
                dstseg = _paired(src, opposite)
                rr = dstseg[0] + r - src[0]
                if dstseg[0] <= rr <= dstseg[1]:
                    for x in range(w):
                        if a[rr][x] == bg:
                            a[rr][x] = color
    return a
